                    if (img1[r][c] === 1 && img2[nr][nc] === 1) {
                        count++;
                    }
                }
            }
        }
        return count;
    }

    for (let dy = -(n - 1); dy <= n - 1; dy++) {
        for (let dx = -(n - 1); dx <= n - 1; dx++) {
